Here is a quick hackaround, it replaces invalid unicode with the replacement char. Though ideally we will track down the code which emitted the invalid unicode (which might be memory error/UB somewhere), which the commented out assert would check.

```diff
diff --git a/src/nvim/screen.c b/src/nvim/screen.c
index a45145172..93a5fd70a 100644
--- a/src/nvim/screen.c
+++ b/src/nvim/screen.c
@@ -5584,6 +5584,12 @@ void grid_puts_len(ScreenGrid *grid, char_u *text, int textlen, int row,
       u8c = utfc_ptr2char(ptr, u8cc);
     }
     mbyte_cells = utf_char2cells(u8c);
+    //assert(mbyte_cells == 1 || mbyte_cells == 2);
+    if (mbyte_cells > 2) {
+      mbyte_cells = 1;
+      u8c = 0xFFFD;
+      u8cc[0] = 0;
+    }
     if (p_arshape && !p_tbidi && arabic_char(u8c)) {
